CREATE TABLE ALLOCATION (ALLOCATIONID NUMBER(19) NOT NULL, ALLOCSTATUS VARCHAR2(255) NULL, ALLOCTYPE VARCHAR2(255) NULL, ALLOCATIONPRICE NUMBER(38) NULL, AVERAGEPRCGRPID NUMBER(19) NULL, AVERAGEPRICE NUMBER(38) NULL, CLEARINGMECHANISM VARCHAR2(255) NULL, CLIENTSSI NUMBER(19) NULL, COMMISSION NUMBER(38) NULL, COMMISSIONAMOUNT NUMBER(38) NULL, COMMISSIONTYPE VARCHAR2(255) NULL, EXCHANGEID NUMBER(19) NULL, FIRMDEPO NUMBER(19) NULL, INSTRUMENTID NUMBER(19) NULL, PAYMENTMETHOD VARCHAR2(255) NULL, QUANTITY NUMBER(38) NULL, SETTLEDATE NUMBER(10) NULL, SUBACCOUNTID NUMBER(19) NULL, TOPACCOUNTID NUMBER(19) NULL, TRADEDATE NUMBER(10) NULL, "VERSION" NUMBER(10) NULL, PRIMARY KEY (ALLOCATIONID))
