CREATE TABLE CLIENTTRADE (CLIENTTRADEID NUMBER(19) NOT NULL, ALLOCATIONID NUMBER(19) NULL, BOOKINGSTATUS VARCHAR2(255) NULL, BOOKINGSUPPRESS NUMBER(1) default 0 NULL, CONFSTATUS VARCHAR2(255) NULL, CONFIRMSUPPRESS NUMBER(1) default 0 NULL, CTMSTATUS VARCHAR2(255) NULL, EXCHANGEID NUMBER(19) NULL, INSTRUMENTID NUMBER(19) NULL, QUANTITY NUMBER(38) NULL, SETTLEDATE NUMBER(10) NULL, TRADEDATE NUMBER(10) NULL, "VERSION" NUMBER(10) NULL, PRIMARY KEY (CLIENTTRADEID))
