CREATE TABLE FIGURATION (FIGURATIONID NUMBER(19) NOT NULL, COMMISSION NUMBER(38) NULL, COMMISSIONAMOUNT NUMBER(38) NULL, COMMISSIONTYPE NUMBER(38) NULL, ENTITYID NUMBER(19) NULL, ENTITYTYPE VARCHAR2(255) NULL, FEE1 NUMBER(38) NULL, FEE2 NUMBER(38) NULL, FEE3 NUMBER(38) NULL, FEE4 NUMBER(38) NULL, FEE5 NUMBER(38) NULL, FEE6 NUMBER(38) NULL, FEE7 NUMBER(38) NULL, FEE8 NUMBER(38) NULL, FEE9 NUMBER(38) NULL, LEVY NUMBER(38) NULL, NETPRICE NUMBER(38) NULL, NETPROCEED NUMBER(38) NULL, NETPROCESSFX NUMBER(38) NULL, PRICE NUMBER(38) NULL, PRINCIPAL NUMBER(38) NULL, QUANTITY NUMBER(38) NULL, TAX NUMBER(38) NULL, TRADEDATE NUMBER(10) NULL, PRIMARY KEY (FIGURATIONID))
