CREATE TABLE ORDERS (ORDERID NUMBER(19) NOT NULL, AVERAGEPRCGRPID NUMBER(19) NULL, BOOKID NUMBER(19) NULL, CAPACITY VARCHAR2(255) NULL, CLIENTID NUMBER(19) NULL, COMMISSION NUMBER(38) NULL, COMMISSIONTYPE VARCHAR2(255) NULL, CURRENCY VARCHAR2(255) NULL, EXCHANGEID NUMBER(19) NULL, EXECUTIONCOUNTRY VARCHAR2(255) NULL, EXECUTIONREGION VARCHAR2(255) NULL, FLOWTYPE VARCHAR2(255) NULL, FOORDERREF VARCHAR2(255) NULL, FRONTOFFICECOMMENT NUMBER(38) NULL, FXDIRECTION VARCHAR2(255) NULL, FXRATE NUMBER(38) NULL, INSTRUMENTID NUMBER(19) NULL, MOCOMMENT VARCHAR2(255) NULL, ORDERSTATUS VARCHAR2(255) NULL, PORTFOLIOID NUMBER(19) NULL, QUANTITY NUMBER(38) NULL, SALESID VARCHAR2(255) NULL, SETTLECONVERSION VARCHAR2(255) NULL, SETTLECURRENCY VARCHAR2(255) NULL, SETTLEDATE NUMBER(10) NULL, SIDE VARCHAR2(255) NULL, TRADEDATE NUMBER(10) NULL, TRADERID VARCHAR2(255) NULL, "VERSION" NUMBER(10) NULL, PRIMARY KEY (ORDERID))
