CREATE TABLE PARTY (PARTYID NUMBER(19) NOT NULL, ACCOUNTTYPE NUMBER(10) NULL, CLIENTREGION NUMBER(10) NULL, NAME NUMBER(19) NULL, SHORTNAME NUMBER(19) NULL, CLIENTCOUNTRY_ID NUMBER(19) NULL, PRIMARY KEY (PARTYID))
